    return a.start < b.start;
}

int main() {
    int n;
    cin >> n;
    vector<Friend> friends(n);
    for (int i = 0; i < n; ++i) {
        cin >> friends[i].gender >> friends[i].start >> friends[i].end;
    }
    sort(friends.begin(), friends.end(), compare);
    int max_friends = 0;
    for (int day = 1; day <= 366; ++day) {
        int males = 0, females = 0;
        for (const auto &friend_ : friends) {
            if (friend_.start <= day && friend_.end >= day) {
                if (friend_.gender == 'M') {
                    ++males;
                } else {
                    ++females;
                }
            }
        }
        max_friends = max(max_friends, 2 * min(males, females));
    }
    cout << max_friends;
}

