            long long x = a[i], y = a[j];
            int currentLength = 2;
            while (true) {
                long long next = x + y;
                if (count.find(next) != count.end()) {
                    if (count[next] > 0) {
                        count[next]--;
                        currentLength++;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
                x = y;
                y = next;
            }
            maxLength = max(maxLength, currentLength);
            int cx = a[i], cy = a[j];
            count[cx]++;
            count[cy]++;
        }
    }

    cout << maxLength;
}

