        iss >> token;
        if (token != "?") {
            result = "Impossible";
            return false;
        }
        numbers.push_back(1);
    }

    int sum = numbers[0];
    for (size_t i = 0; i < operations.size(); ++i) {
        if (operations[i] == '+') {
            sum += numbers[i + 1];
        } else {
            sum -= numbers[i + 1];
        }
    }

    int remaining = n - sum;
    if (remaining < 0 || remaining > numbers.size()) {
        result = "Impossible";
