        adj[v].push_back(u);
    }

    vector<int> degree(n+1);
    for(int i = 1; i <= n; ++i) {
        degree[i] = adj[i].size();
    }

    queue<int> q;
    vector<int> result1, result2;
    vector<bool> covered(n+1, false);

    // Find leaves and add to one vertex cover
    for(int i = 1; i <= n; ++i) {
        if(degree[i] == 1) {
            q.push(i);
        }
    }

    while(!q.empty()) {
        int node = q.front();
        q.pop();
        if(!covered[node]) {
            covered[node] = true;
            result1.push_back(node);
            for(auto neighbor : adj[node]) {
                if(--degree[neighbor] == 1) {
                    q.push(neighbor);
                }
            }
        }
    }

    vector<bool> visited(n+1, false);

    // Find another vertex cover using BFS
    for(int i = 1; i <= n; ++i) {
