const int MAX_BITS = 18;

unordered_map<int, int> count;
int bitCount[MAX_BITS][2];

void updateCount(long long num, int delta) {
    int bitIndex = 0;
    while (num > 0 || bitIndex < MAX_BITS) {
        int bit = (bitIndex < MAX_BITS && (num & 1)) ? 1 : 0;
        bitCount[bitIndex][bit] += delta;
        num >>= 1;
        bitIndex++;
    }
}

int matchPattern(string &pattern) {
    int result = count[pattern.size()];
    int patLen = pattern.size();
    for (int i = 0; i < patLen; i++) {
        if (pattern[patLen - i - 1] == '0') {
            result += bitCount[i][0];
            result -= bitCount[i][1];
        } else {
            result -= bitCount[i][0];
            result += bitCount[i][1];
        }
    }
    return result;
}

