#include <bits/stdc++.h>
using namespace std;

const int MAX_PATTERN = 18;
const int MAX_VAL = 1 << MAX_PATTERN;

struct TrieNode {
    TrieNode* child[2];
    int count;

    TrieNode() {
        child[0] = child[1] = nullptr;
        count = 0;
    }
};

void add(TrieNode* root, long long num) {
    TrieNode* node = root;
    for (int i = MAX_PATTERN - 1; i >= 0; --i) {
        int bit = (num >> i) & 1;
        if (!node->child[bit]) {
            node->child[bit] = new TrieNode();
        }
        node = node->child[bit];
        ++node->count;
    }
}

void remove(TrieNode* root, long long num) {
    TrieNode* node = root;
    for (int i = MAX_PATTERN - 1; i >= 0; --i) {
        int bit = (num >> i) & 1;
        node = node->child[bit];
        --node->count;
    }
}

int query(TrieNode* root, const string& pattern) {
    TrieNode* node = root;
    for (int i = MAX_PATTERN - 1, j = pattern.size() - 1; i >= 0; --i) {
        if (node == nullptr) return 0;
        if (j >= 0 && pattern[j] == '0') {
            node = node->child[0];
        } else if (j >= 0 && pattern[j] == '1') {
            node = node->child[1];
        } else {
            int res = 0;
            if (node->child[0]) res += node->child[0]->count;
            if (node->child[1]) res += node->child[1]->count;
            return res;
        }
        --j;
    }
    return node ? node->count : 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    TrieNode* root = new TrieNode();
    while (t--) {
        char type;
        cin >> type;
        if (type == '+') {
            long long num;
            cin >> num;
            add(root, num);
        } else if (type == '-') {
            long long num;
            cin >> num;
            remove(root, num);
        } else {
            string pattern;
            cin >> pattern;
            cout << query(root, pattern) << "\n";
        }
    }
    return 0;
}

