void updatePattern(long long num, int delta) {
    string bin = "";
    while (num > 0) {
        bin += (num % 2 == 0 ? '0' : '1');
        num /= 2;
    }
    reverse(bin.begin(), bin.end());
    int len = bin.size();
    len = min(len, MAX_PATTERN);
    for (int subLen = 1; subLen <= len; ++subLen) {
        string subBin = bin.substr(len - subLen);
        while (subBin.size() < subLen) {
            subBin = "0" + subBin;
        }
        int mask = 0;
        for (int i = 0; i < subLen; ++i) {
            mask |= ((subBin[i] == '1') ? 1 : 0) << i;
        }
        countPatterns[subLen][mask] += delta;
    }
}

