        long long b = pq.top(); pq.pop();
        pq.push(a + b + 1);
    }

    long long totalCost = pq.top();
    long long zeroCount = 0, oneCount = 0;
    countZeroAndOne(totalCost, zeroCount, oneCount);

    long long result = zeroCount * c0 + oneCount * c1;
    cout << result << endl;

    return 0;
}

void countZeroAndOne(long long num, long long &zeroCount, long long &oneCount) {
    while (num > 0) {
        if (num % 2 == 0) {
            zeroCount++;
        } else {
            oneCount++;
        }
        num /= 2;
    }
}

