        cin >> students[i].sports;
    }

    vector<Student> programmingTeam;
    vector<Student> sportsTeam;

    sort(students.begin(), students.end(), compareProgramming);

    for (int i = 0; i < p; i++) {
        programmingTeam.push_back(students[i]);
    }

    sort(students.begin(), students.end(), compareSports);

    for (int i = 0; i < s; i++) {
        sportsTeam.push_back(students[i]);
    }

    int programmingStrength = 0;
    int sportsStrength = 0;
    vector<int> programmingIndices;
    vector<int> sportsIndices;

    for (const auto &student : programmingTeam) {
        programmingStrength += student.programming;
        programmingIndices.push_back(student.index);
