    for (int i = 0; i < n; ++i) {
        cin >> piece[i];
        totalX += count(piece[i].begin(), piece[i].end(), 'X');
    }
    if (totalX % 2 != 0) {
        cout << "NO";
        return 0;
    }
    totalX /= 2;
    vector<vector<bool>> occupied(n, vector<bool>(m * 2, false));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (piece[i][j] == 'X') {
                if (!occupied[i][j] && !occupied[i][j + m]) {
                    occupied[i][j] = true;
                    occupied[i][j + m] = true;
                    totalX -= 2;
                }
            }
        }
    }
    if (totalX == 0) {
        cout << "YES";
    } else {
        cout << "NO";
    }
}

