#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for(int i = 0; i < n; ++i) cin >> grid[i];

    vector<pair<int, int>> shape;
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < m; ++j){
            if(grid[i][j] == 'X') shape.push_back({i, j});
        }
    }

    int min_x = INT_MAX, min_y = INT_MAX;
    for(auto [x, y] : shape){
        min_x = min(min_x, x);
        min_y = min(min_y, y);
    }

    for(auto &[x, y] : shape){
        x -= min_x;
        y -= min_y;
    }

    int max_x = 0, max_y = 0;
    for(auto [x, y] : shape){
        max_x = max(max_x, x);
        max_y = max(max_y, y);
    }

    int width = max_y + 1, height = max_x + 1;
    int size = shape.size();

    for(int dx = -width + 1; dx <= width - 1; ++dx){
        for(int dy = -height + 1; dy <= height - 1; ++dy){
            bool valid = true;
            unordered_set<int> seen;
            for(auto [x, y] : shape){
                seen.insert(x * m + y);
            }
            for(auto [x, y] : shape){
                int nx = x + dx, ny = y + dy;
                if(nx < 0 || nx >= height || ny < 0 || ny >= width) {
                    valid = false;
                    break;
                }
                if(seen.count(nx * m + ny)){
                    valid = false;
                    break;
                }
            }
            if(valid){
                cout << "YES";
                return 0;
            }
        }
    }
    cout << "NO";
}

