const int dx[] = {0, 0, 1, -1};
const int dy[] = {1, -1, 0, 0};

bool bfs(vector<string>& grid, int n, int m, int sx, int sy, vector<vector<bool>>& visited) {
    queue<pair<int, int>> q;
    q.push({sx, sy});
    visited[sx][sy] = true;
    int area = 1;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny] && grid[nx][ny] == 'X') {
                visited[nx][ny] = true;
                q.push({nx, ny});
                ++area;
            }
        }
    }

    int width = 0, height = 0;
    vector<vector<bool>> tempVisited(n, vector<bool>(m, false));
    q.push({sx, sy});
    tempVisited[sx][sy] = true;

    while (!q.empty()) {
        int size = q.size();
        ++height;

        for (int i = 0; i < size; ++i) {
            auto [x, y] = q.front();
            q.pop();

            for (int dir = 0; dir < 4; ++dir) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];

