bool canFormRectangle(const vector<string>& piece, int n, int m) {
    int countX = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (piece[i][j] == 'X') {
                ++countX;
            }
        }
    }
    int side1 = sqrt(countX * 2);
    if (side1 * side1 != countX * 2) {
        return false;
    }
    int side2 = countX * 2 / side1;
    vector<string> combined(side1, string(side2 * 2, '.'));

    for (int dx = 0; dx <= side2; ++dx) {
        for (int dy = 0; dy <= side1; ++dy) {
            bool valid = true;
            for (int i = 0; i < n && valid; ++i) {
                for (int j = 0; j < m && valid; ++j) {
                    if (piece[i][j] == 'X') {
                        if (combined[dy + i][dx + j] == 'X') {
                            valid = false;
                        } else {
                            combined[dy + i][dx + j] = 'X';
                        }
                    }
                }
            }
            if (valid) {
                for (int i = 0; i < n && valid; ++i) {
                    for (int j = 0; j < m && valid; ++j) {
                        if (piece[i][j] == 'X') {
                            if (combined[dy + i][dx + j + side2] == 'X') {
                                valid = false;
                            } else {
                                combined[dy + i][dx + j + side2] = 'X';
                            }
                        }
                    }
                }
            }
            if (valid) {
                return true;
            }
            for (int i = 0; i < side1; ++i) {
                fill(combined[i].begin(), combined[i].end(), '.');
            }
        }
    }
    return false;
}

