using namespace std;

bool isValidPassword(const string& password) {
    bool hasDigit = false, hasLower = false, hasSpecial = false;
    for (char c : password) {
        if (isdigit(c)) hasDigit = true;
        else if (islower(c)) hasLower = true;
        else if (c == '#' || c == '*' || c == '&') hasSpecial = true;
    }
    return hasDigit && hasLower && hasSpecial;
}

int minOperationsToValidPassword(int n, int m, const vector<string>& strings) {
    int minOps = INT_MAX;
    for (int i = 0; i < m; ++i) {
        string password;
        for (const string& s : strings) {
            password += s[i];
        }
        if (isValidPassword(password)) {
            minOps = 0;
            break;
        }
    }
    if (minOps == 0) return minOps;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int k = 1; k <= m / 2; ++k) {
                int opsRight = k;
                int opsLeft = m - k;
                string passwordRight = strings[i].substr(j + 1) + strings[i].substr(0, j + 1) + strings[i].substr(j, 1);
                string passwordLeft = strings[i].substr(j - k + 1) + strings[i].substr(0, j - k + 1) + strings[i].substr(j, 1);

                for (int l = 0; l < n; ++l) {
                    if (l != i) {
                        passwordRight += strings[l][0];
                        passwordLeft += strings[l][0];
                    }
                }

                if (isValidPassword(passwordRight)) {
                    minOps = min(minOps, opsRight);
                }
                if (isValidPassword(passwordLeft)) {
                    minOps = min(minOps, opsLeft);
                }
            }
        }
    }
    return minOps;
}

int main() {
