vector<int> findLCIS(const vector<int>& a, const vector<int>& b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<int>> path(n + 1, vector<int>(m + 1));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                int len = 1;
                int prevI = -1, prevJ = -1;
                for (int k = 1; k < i; ++k) {
                    for (int l = 1; l < j; ++l) {
                        if (a[k - 1] < a[i - 1] && dp[k][l] + 1 > len) {
                            len = dp[k][l] + 1;
                            prevI = k;
                            prevJ = l;
                        }
                    }
                }
                dp[i][j] = len;
                path[i][j] = prevJ * (n + 1) + prevI;
            }
        }
    }

    int maxlen = 0, maxi = -1, maxj = -1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (dp[i][j] > maxlen) {
                maxlen = dp[i][j];
                maxi = i;
                maxj = j;
            }
        }
    }

    vector<int> lcis;
    while (maxi > 0 && maxj > 0) {
        lcis.push_back(a[maxi - 1]);
        int prev = path[maxi][maxj];
        maxi = prev % (n + 1);
        maxj = prev / (n + 1);
    }
    reverse(lcis.begin(), lcis.end());

    return lcis;
}

