vector<int> findLCIS(const vector<int>& a, const vector<int>& b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<pair<int, int>>> prev(n + 1, vector<pair<int, int>>(m + 1));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                if (dp[i - 1][j - 1] + 1 > dp[i][j]) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                    prev[i][j] = {i - 1, j - 1};
                }
            }
            if (dp[i - 1][j] > dp[i][j]) {
                dp[i][j] = dp[i - 1][j];
                prev[i][j] = {i - 1, j};
            }
            if (dp[i][j - 1] > dp[i][j]) {
                dp[i][j] = dp[i][j - 1];
                prev[i][j] = {i, j - 1};
            }
        }
    }

    int i = n, j = m;
    vector<int> lcis;
    while (i > 0 && j > 0) {
        if (prev[i][j] == make_pair(i - 1, j - 1)) {
            lcis.push_back(a[i - 1]);
            --i;
            --j;
        } else if (prev[i][j] == make_pair(i - 1, j)) {
            --i;
        } else {
            --j;
        }
    }
