    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<bool>> path(n + 1, vector<bool>(m + 1, false));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                path[i][j] = true;
            } else {
                if (dp[i - 1][j] > dp[i][j - 1]) {
                    dp[i][j] = dp[i - 1][j];
                } else {
                    dp[i][j] = dp[i][j - 1];
                }
            }
        }
    }

    vector<int> result;
    int i = n, j = m;
    while (i > 0 && j > 0) {
        if (path[i][j]) {
            result.push_back(a[i - 1]);
            --i;
            --j;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            --i;
        } else {
            --j;
        }
    }
