#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <algorithm>
using namespace std;

struct Item {
    string name;
    string type;
    int atk;
    int def;
    int res;
    int size;
    vector<int> bonuses_atk;
    vector<int> bonuses_def;
    vector<int> bonuses_res;
};

struct Resident {
    string name;
    string type;
    int bonus;
    string home;
};

bool compareItemsAtk(const Item& a, const Item& b) {
    return a.atk > b.atk || (a.atk == b.atk && a.name < b.name);
}

bool compareItemsDef(const Item& a, const Item& b) {
    return a.def > b.def || (a.def == b.def && a.name < b.name);
}

bool compareItemsRes(const Item& a, const Item& b) {
    return a.res > b.res || (a.res == b.res && a.name < b.name);
}

int main() {
    int n;
    cin >> n;
    vector<Item> items(n);
    map<string, int> itemIndex;
    for (int i = 0; i < n; ++i) {
        cin >> items[i].name >> items[i].type >> items[i].atk >> items[i].def >> items[i].res >> items[i].size;
        itemIndex[items[i].name] = i;
