    int size;
    int currentResidents;
};

struct Resident {
    std::string name;
    std::string type;
    int bonus;
    std::string home;
};

int main() {
    int n;
    std::cin >> n;
    std::vector<Item> items(n);
    std::map<std::string, Item&> itemMap;

    for (auto& item : items) {
        std::cin >> item.name >> item.klass >> item.atk >> item.def >> item.res >> item.size;
        item.currentResidents = 0;
        itemMap[item.name] = item;
    }

    int k;
    std::cin >> k;
    std::vector<Resident> residents(k);
    std::vector<std::string> residentNames[k];

    for (auto& resident : residents) {
        std::cin >> resident.name >> resident.type >> resident.bonus >> resident.home;
        residentNames[resident.type == "gladiator" ? 0 : resident.type == "sentry" ? 1 : 2].push_back(resident.name);
        itemMap[resident.home].currentResidents++;
    }

    for (int i = 0; i < 3; ++i) {
        std::sort(residentNames[i].begin(), residentNames[i].end(), [&residents](const std::string& a, const std::string& b) {
            return std::find_if(residents.begin(), residents.end(), [&a](const Resident& r) { return r.name == a; })->bonus >
                   std::find_if(residents.begin(), residents.end(), [&b](const Resident& r) { return r.name == b; })->bonus;
        });
    }

    auto compareItems = [&itemMap, &residents, &residentNames](const Item& a, const Item& b) {
        if (a.atk != b.atk) return a.atk > b.atk;
        if (a.def != b.def) return a.def > b.def;
        if (a.res != b.res) return a.res > b.res;
        if (a.size - a.currentResidents != b.size - b.currentResidents) return a.size - a.currentResidents > b.size - b.currentResidents;
        return false;
    };

    Item bestWeapon, bestArmor, bestOrb;

    for (auto& item : items) {
        if (item.klass == "weapon") {
            if (!bestWeapon.name.size() || compareItems(item, bestWeapon)) {
                bestWeapon = item;
            }
        } else if (item.klass == "armor") {
            if (!bestArmor.name.size() || compareItems(item, bestArmor)) {
                bestArmor = item;
            }
        } else if (item.klass == "orb") {
            if (!bestOrb.name.size() || compareItems(item, bestOrb)) {
                bestOrb = item;
            }
        }
    }

    auto assignResidents = [&](Item& item, int typeIndex) {
        for (int j = 0; j < residentNames[typeIndex].size(); ++j) {
            auto& resident = *std::find_if(residents.begin(), residents.end(), [&](const Resident& r) { return r.name == residentNames[typeIndex][j]; });
            if (itemMap[resident.home].currentResidents > itemMap[resident.home].size - (item.currentResidents < item.size)) continue;
            resident.home = item.name;
            item.currentResidents++;
            if (item.currentResidents == item.size) break;
        }
        itemMap[item.name] = item;
    };

    std::vector<int> typeOrder = {0, 1, 2};
    do {
        Item tempWeapon = bestWeapon, tempArmor = bestArmor, tempOrb = bestOrb;
        tempWeapon.currentResidents = 0;
        tempArmor.currentResidents = 0;
        tempOrb.currentResidents = 0;

        assignResidents(tempWeapon, 0);
        if (tempWeapon.currentResidents + tempArmor.currentResidents + tempOrb.currentResidents < k) assignResidents(tempArmor, 1);
        if (tempWeapon.currentResidents + tempArmor.currentResidents + tempOrb.currentResidents < k) assignResidents(tempOrb, 2);

        if (!itemMap[bestWeapon.name].klass.size() || compareItems(tempWeapon, itemMap[bestWeapon.name])) {
            bestWeapon = tempWeapon;
            bestArmor = tempArmor;
            bestOrb = tempOrb;
        }
    } while (std::next_permutation(typeOrder.begin(), typeOrder.end()));

    auto printItem = [&itemMap, &residents](const Item& item) {
        std::cout << item.name << " " << item.currentResidents;
        for (auto& residentName : residentNames[0]) {
            auto& resident = *std::find_if(residents.begin(), residents.end(), [&](const Resident& r) { return r.name == residentName; });
            if (resident.home == item.name) std::cout << " " << resident.name;
        }
        for (auto& residentName : residentNames[1]) {
            auto& resident = *std::find_if(residents.begin(), residents.end(), [&](const Resident& r) { return r.name == residentName; });
            if (resident.home == item.name) std::cout << " " << resident.name;
        }
        for (auto& residentName : residentNames[2]) {
            auto& resident = *std::find_if(residents.begin(), residents.end(), [&](const Resident& r) { return r.name == residentName; });
            if (resident.home == item.name) std::cout << " " << resident.name;
        }
        std::cout << "\n";
    };

