    int bonus;
    string home;
};

bool compareWeapons(const Item& a, const Item& b) {
    return a.atk > b.atk || (a.atk == b.atk && a.residents.size() > b.residents.size());
}

bool compareArmors(const Item& a, const Item& b) {
    return a.def > b.def || (a.def == b.def && a.residents.size() > b.residents.size());
}

bool compareOrbs(const Item& a, const Item& b) {
    return a.res > b.res || (a.res == b.res && a.residents.size() > b.residents.size());
}

pair<bool, int> canMoveResident(Item& source, Item& dest) {
    if (source.residents.empty() || dest.size <= dest.residents.size())
        return {false, -1};
    int maxBonus = 0;
    string residentToMove;
    for (const auto& resident : source.residents) {
        if (resident == "")
            continue;
        int bonus = 0;
        if (dest.type == "weapon" && resident[0] == 'g')
            bonus = stol(resident.substr(1));
        else if (dest.type == "armor" && resident[0] == 's')
            bonus = stol(resident.substr(1));
        else if (dest.type == "orb" && resident[0] == 'p')
            bonus = stol(resident.substr(1));
        if (bonus > maxBonus) {
            maxBonus = bonus;
            residentToMove = resident;
        }
    }
    if (maxBonus > 0) {
        source.residents.erase(find(source.residents.begin(), source.residents.end(), residentToMove));
        dest.residents.push_back(residentToMove);
