#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

string s;
int k;

struct suffix {
    int index;
    pair<int, int> rank;
};

bool compare(struct suffix a, struct suffix b) {
    if (a.rank.first == b.rank.first) {
        return (a.rank.second < b.rank.second);
    } else {
        return (a.rank.first < b.rank.first);
    }
}

vector<int> build_suffix_array() {
    int n = s.length();
    vector<struct suffix> suffixes(n);

    for (int i = 0; i < n; i++) {
        suffixes[i].index = i;
        suffixes[i].rank.first = s[i] - 'a';
        suffixes[i].rank.second = (i + 1 < n) ? (s[i + 1] - 'a') : -1;
    }

    sort(suffixes.begin(), suffixes.end(), compare);

    vector<int> suffix_arr(n);

    vector<int> inv_suffix_arr(n);

    int k = 4;
    while (k < 2 * n) {
        int rank = 0;
        int prev_rank = suffixes[0].rank.first;
        suffixes[0].rank.first = rank;
        inv_suffix_arr[suffixes[0].index] = 0;

        for (int i = 1; i < n; i++) {
            if (suffixes[i].rank.first == prev_rank && suffixes[i].rank.second == suffixes[i - 1].rank.second) {
                prev_rank = suffixes[i].rank.first;
                suffixes[i].rank.first = rank;
            } else {
                prev_rank = suffixes[i].rank.first;
                suffixes[i].rank.first = ++rank;
            }
            inv_suffix_arr[suffixes[i].index] = i;
        }

        for (int i = 0; i < n; i++) {
            int nextindex = suffixes[i].index + k / 2;
            suffixes[i].rank.second = (nextindex < n) ? suffixes[inv_suffix_arr[nextindex]].rank.first : -1;
        }

        sort(suffixes.begin(), suffixes.end(), compare);

        k *= 2;
    }

    for (int i = 0; i < n; i++)
        suffix_arr[i] = suffixes[i].index;

    return suffix_arr;
}

vector<int> kasai(vector<int> suffix_arr) {
    int n = s.length();
    vector<int> lcp(n, 0);

    vector<int> inv_suffix_arr(n);

    for (int i = 0; i < n; i++)
        inv_suffix_arr[suffix_arr[i]] = i;

    int k = 0;

    for (int i = 0; i < n; i++) {
        if (inv_suffix_arr[i] == n - 1) {
            k = 0;
            continue;
        }

        int j = suffix_arr[inv_suffix_arr[i] + 1];

        while (i + k < n && j + k < n && s[i + k] == s[j + k])
            k++;

        lcp[inv_suffix_arr[i]] = k;

        if (k > 0)
            k--;
    }

    return lcp;
}

int main(){
    cin >> s >> k;

    vector<int> suffix_arr = build_suffix_array();
    vector<int> lcp = kasai(suffix_arr);

    int total_substrings = (s.length() * (s.length() + 1)) / 2;

    if(k > total_substrings){
        cout << "No such line.";
        return 0;
    }

    int res = 0;
    for(int i = 0; i < s.length(); ++i){
        int length = s.length() - suffix_arr[i];
        int num_substrings_here = length - lcp[i];

        if(k <= num_substrings_here){
            res = i;
            break;
        }
        k -= num_substrings_here;
    }

    string resultString = s.substr(suffix_arr[res], suffix_arr[res] + k);
    cout << resultString;

    return 0;
}

