#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct SuffixArray {
    string s;
    int n;
    vector<int> sa;
    vector<int> rank;
    vector<int> lcp;

    SuffixArray(const string &s) : s(s), n(s.size()), sa(n), rank(n), lcp(n) {
        build_sa();
        build_rank();
        build_lcp();
    }

    void build_sa() {
        vector<pair<char, int>> a(n);
        for (int i = 0; i < n; i++) a[i] = {s[i], i};
        sort(a.begin(), a.end());
        sa[0] = a[0].second;
        rank[a[0].second] = 0;
        for (int i = 1; i < n; i++) {
            sa[i] = a[i].second;
            rank[a[i].second] = rank[a[i - 1].second] + (a[i].first != a[i - 1].first);
        }
        vector<int> c(n), cn(n);
        for (int k = 0; (1 << k) < n; k++) {
            for (int i = 0; i < n; i++) {
                c[i] = rank[sa[i]];
                cn[(sa[i] - (1 << k) + n) % n] = c[i];
            }
            int classes = 1;
            for (int i = 1; i < n; i++) {
                if (cn[i] != cn[i - 1] || c[(sa[i] + (1 << k)) % n] != c[(sa[i - 1] + (1 << k)) % n]) {
                    classes++;
                }
                rank[sa[i]] = classes - 1;
            }
            swap(c, cn);
        }
    }

    void build_rank() {
        rank[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            rank[sa[i]] = rank[sa[i - 1]] + (s[sa[i]] != s[sa[i - 1]]);
        }
    }

    void build_lcp() {
        int k = 0;
        for (int i = 0; i < n; i++) {
            if (rank[i] == n - 1) {
                k = 0;
                continue;
            }
            int j = sa[rank[i] + 1];
            while (i + k < n && j + k < n && s[i + k] == s[j + k]) k++;
            lcp[rank[i]] = k;
            k = max(k - 1, 0);
        }
    }

    long long count_substrings() {
        long long res = 1LL * n * (n + 1) / 2;
        for (int i = 1; i < n; i++) {
            res -= lcp[i];
        }
        return res;
    }

    string kth_substring(long long k) {
        if (k > count_substrings()) return "No such line.";
        for (int i = 0; i < n; i++) {
            long long count = n - sa[i] - (i == 0 ? 0 : lcp[i - 1]);
            if (k <= count) {
                return s.substr(sa[i], k);
            }
            k -= count;
        }
        return "No such line.";
    }
};

int main() {
    string s;
    long long k;
    cin >> s >> k;
    SuffixArray sa(s);
    cout << sa.kth_substring(k);
}

