#include <vector>
#include <algorithm>
#include <set>

using namespace std;

void dfs(const string& s, int p, string& chosen, set<string>& outcomes) {
    if (p == s.size()) {
        if (chosen.size() == 2) {
            outcomes.insert(chosen);
        }
        return;
    }
    if (s[p] != '?') {
        chosen += s[p];
        dfs(s, p + 1, chosen, outcomes);
        chosen.pop_back();
    } else {
        chosen += '0';
        dfs(s, p + 1, chosen, outcomes);
        chosen.pop_back();
        chosen += '1';
        dfs(s, p + 1, chosen, outcomes);
        chosen.pop_back();
    }
}

int main() {
    string s;
    cin >> s;
    set<string> outcomes;
    string chosen;
    dfs(s, 0, chosen, outcomes);
    for (const auto& outcome : outcomes) {
