void generateOutcomes(const string &s, int start, int end, set<string> &outcomes) {
    if (end - start == 2) {
        outcomes.insert(s.substr(start, 2));
        return;
    }
    for (int i = start; i < end; ++i) {
        string new_s = s.substr(start, i - start) + s.substr(i + 1);
        if (new_s[start] == '0' && new_s[end - 2] == '0') {
            outcomes.insert("00");
            continue;
