        if (new_s[start] == '1' && new_s[end - 2] == '1') {
            outcomes.insert("11");
            continue;
        }
        generateOutcomes(new_s, start, end - 1, outcomes);
        generateOutcomes(new_s, start + 1, end - 1, outcomes);
        generateOutcomes(new_s, start + 1, end, outcomes);
    }
}

void solve(const string &s) {
    set<string> allOutcomes;
    string complete = s;
    int questionMarks = count(s.begin(), s.end(), '?');
