    std::stringstream ss;
    char prev = ' ';
    for (char c : text) {
        if (c == ',' || c == '.' || c == '!' || c == '?') {
            if (prev != ' ') ss << ' ';
            ss << c;
            if (prev != ' ') ss << ' ';
        } else if (c != ' ') {
            if (prev == ' ' && ss.tellp() != 0) ss << ' ';
            ss << c;
        }
