    for (int i = 0; i < trolleys.size(); ++i) {
        double t = trolleys[i].t;
        double v = trolleys[i].v;
        double t1 = (v - sqrt(max(0.0, v*v - 2*a*(mid - t)))) / a;
        double dist1 = v * t1 - a * t1 * t1 / 2;
