        double t3 = mid - t - t1 - t2;
        double dist3 = v * t3;
        double dist = dist1 + dist2 + dist3;
        if (dist >= d) {
            if (t + t1 + t2 <= prev_time) {
                return false;
            }
            prev_time = t + t1 + t2;
        } else {
            double t1_prime = (v - sqrt(max(0.0, v*v - 2*a*(d - dist2 - dist3)))) / a;
            double t2_prime = sqrt(2 * a * (d - dist2 - dist3)) / a;
            double t3_prime = mid - t - t1_prime - t2_prime;
            double dist1_prime = v * t1_prime - a * t1_prime * t1_prime / 2;
            double dist_prime = dist1_prime + dist2 + dist3;
            if (dist_prime < d) {
                return false;
            }
            if (t + t1_prime + t2_prime <= prev_time) {
                return false;
            }
            prev_time = t + t1_prime + t2_prime;
