double minTimeToStation(double ti, double vi, double a, double d, double prevTime) {
    double maxSpeedTime = vi / a;
    double maxSpeedDistance = 0.5 * a * maxSpeedTime * maxSpeedTime;
    if (maxSpeedDistance >= d) {
        return ti + sqrt(2 * d / a);
    }
    double remainingDistance = d - maxSpeedDistance;
    double remainingTime = remainingDistance / vi;
    double catchUpTime = prevTime - ti;
    double catchUpDistance = 0.5 * a * catchUpTime * catchUpTime;
    if (catchUpDistance >= maxSpeedDistance) {
        return prevTime;
    }
    double relativeDistance = maxSpeedDistance - catchUpDistance;
    if (relativeDistance <= remainingDistance) {
        double additionalTime = sqrt(2 * relativeDistance / a);
        return ti + maxSpeedTime + additionalTime;
    }
    return ti + maxSpeedTime + (remainingDistance - relativeDistance) / (vi - a * catchUpTime);
}

