int count_inversions(const vector<int>& seq, int len) {
    int inversions = 0;
    for (int i = 0; i < len; ++i) {
        for (int j = i + 1; j < len; ++j) {
            if (seq[i] > seq[j]) {
                ++inversions;
            }
        }
    }
    return inversions;
}

bool is_subsequence(const vector<int>& les_seq, const vector<int>& arc_seq) {
    int les_idx = 0, arc_idx = 0;
    int les_len = les_seq.size(), arc_len = arc_seq.size();
    while (les_idx < les_len && arc_idx < arc_len) {
        if (les_seq[les_idx] == arc_seq[arc_idx]) {
            ++les_idx;
        }
        ++arc_idx;
    }
    return les_idx == les_len;
}

