    sizes[node] = 1;
    for (int& child : adj[node]) {
        if (child != parent) {
            dfs(child, node);
            sizes[node] += sizes[child];
        }
    }
}

long long max_product(int n) {
    long long res = 1;
    vector<int> all_sizes;
    for (int i = 1; i <= n; ++i) {
        if (sizes[i] > 0) {
            all_sizes.push_back(sizes[i]);
        }
    }
    sort(all_sizes.begin(), all_sizes.end());
    reverse(all_sizes.begin(), all_sizes.end());
    for (int i = 0; i < all_sizes.size(); ++i) {
        if (i == all_sizes.size() - 2 && all_sizes[i] * all_sizes[i + 1] >= n) {
            break;
        }
        if (all_sizes[i] == n) {
            n = all_sizes[i];
            all_sizes[i] = 0;
        } else {
            res *= all_sizes[i];
            n -= all_sizes[i];
        }
    }
    return res * n;
}

