vector<bool> sieve(int maxn) {
    vector<bool> is_prime(maxn + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= maxn; ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j <= maxn; j += i) {
                is_prime[j] = false;
            }
        }
    }
    return is_prime;
