#include <algorithm>
using namespace std;

bool canPlugAllDevices(int n, int m, int k, const vector<int>& filters, int selected) {
    vector<int> largestFilters;
    for (int i = 0; i < selected; ++i) {
        largestFilters.push_back(filters[i]);
    }
    int extraSockets = k - 1; // We use one socket to plug the first filter
    for (int i = 1; i < selected; ++i) {
        largestFilters[i] -= 1; // Each filter after the first one uses one socket to plug in
        extraSockets += largestFilters[i];
    }
    extraSockets += largestFilters[0];
    return extraSockets >= m;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<int> filters(n);
    for (int i = 0; i < n; ++i) {
        cin >> filters[i];
    }
    sort(filters.begin(), filters.end(), greater<int>());

    for (int i = 1; i <= n; ++i) {
        if (canPlugAllDevices(n, m, k, filters, i)) {
            cout << i;
            return 0;
        }
    }
    cout << -1;
    return 0;
