bool place2x2(int n, int m, int &c, vector<string> &board, char type) {
    for (int i = 0; i + 1 < n; ++i) {
        for (int j = 0; j + 1 < m; ++j) {
            if (board[i][j] == '.' && board[i][j + 1] == '.' && board[i + 1][j] == '.' && board[i + 1][j + 1] == '.') {
                if (c > 0) {
                    board[i][j] = board[i][j + 1] = board[i + 1][j] = board[i + 1][j + 1] = type;
                    --c;
                    return true;
                }
            }
        }
    }
    return false;
}

bool place1x2(int n, int m, int &a, int &b, vector<string> &board) {
    char type = 'a';
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j + 1 < m; ++j) {
            if (board[i][j] == '.' && board[i][j + 1] == '.') {
                if (a > 0) {
                    board[i][j] = board[i][j + 1] = type;
                    --a;
                    ++type;
                    return true;
                }
            }
        }
    }
    for (int j = 0; j < m; ++j) {
        for (int i = 0; i + 1 < n; ++i) {
            if (board[i][j] == '.' && board[i + 1][j] == '.') {
                if (b > 0) {
                    board[i][j] = board[i + 1][j] = type;
                    --b;
                    ++type;
                    return true;
                }
            }
        }
    }
    return false;
}

