    int total_turns = 2 * (layer - 1);
    if (x == layer && y == -layer + 1) {
        total_turns += 0;
    } else if (x == layer && y == layer) {
        total_turns += 1;
    } else if (x == -layer + 1 && y == layer) {
        total_turns += 2;
    } else if (x == -layer && y == layer) {
        total_turns += 3;
    } else if (x == -layer && y == -layer + 1) {
        total_turns += 4;
    } else if (x == -layer && y == -layer) {
        total_turns += 5;
    } else if (x == -layer + 1 && y == -layer) {
        total_turns += 6;
    } else if (x == layer && y == -layer) {
