        cout << 0;
        return 0;
    }
    int dist = max(abs(x), abs(y));
    int layer = 2 * (dist - 1);
    int turns = layer + 1;
    if (x == dist) turns -= dist - y;
    else if (y == dist) turns -= dist - x;
    else if (x == -dist) turns -= abs(y) - dist;
    else if (y == -dist) turns -= abs(x) - dist;
    cout << turns;
}

