vector<vector<int>> buildGraph(int n, const vector<int>& favs) {
    vector<vector<int>> graph(n);
    for (int i = 0; i < n; ++i) {
        int favorite = favs[i];
        if (i + favorite < n) graph[i].push_back(i + favorite);
        if (i - favorite >= 0) graph[i].push_back(i - favorite);
    }
    return graph;
}

bool canReachPermutation(int n, const vector<int>& perm, const vector<int>& favs) {
    vector<vector<int>> graph = buildGraph(n, favs);
    vector<int> color(n, -1);

    queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (color[i] == -1) {
            q.push(i);
            color[i] = perm[i] - 1;

            while (!q.empty()) {
