#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>

using namespace std;

bool canSort(int n, const vector<int>& perm, const vector<int>& fav) {
    vector<vector<int>> graph(n);
    for (int i = 0; i < n; ++i) {
        int to = (i + fav[i]) % n;
        graph[i].push_back(to);
        graph[to].push_back(i);
    }

    vector<int> visited(n, 0);
    for (int i = 0; i < n; ++i) {
        if (visited[i] == 0) {
            queue<int> q;
            int currentComponent = -1;
            q.push(i);
            visited[i] = 1;
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                if (currentComponent == -1) {
                    currentComponent = perm[v] - 1;
                } else if (currentComponent != perm[v] - 1) {
                    return false;
                }
                for (int u : graph[v]) {
                    if (visited[u] == 0) {
                        visited[u] = 1;
                        q.push(u);
                    }
                }
            }
        }
    }
    return true;
}

