    int sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += eggs[i].first;
    }
    int target = sum / 2;
    vector<bool> dp(target + 1, false);
    dp[0] = true;
    for (int i = 0; i < n; ++i) {
        for (int j = target; j >= eggs[i].first; --j) {
            dp[j] = dp[j] || dp[j - eggs[i].first];
        }
    }
    int closest = -1;
    for (int i = 0; i <= target; ++i) {
        if (dp[i]) {
            closest = i;
        }
    }
    int sa = closest;
    int sg = sum - closest;
    int diff = abs(sa - sg);
    if (diff > 500) {
        cout << "-1";
        return 0;
    }
    string result(n, 'G');
    target = sa;
    for (int i = n - 1; i >= 0; --i) {
        if (target >= eggs[i].first && dp[target - eggs[i].first]) {
            result[i] = 'A';
            target -= eggs[i].first;
        }
    }
    cout << result;
}

