        int ti;
        std::cin >> ti;

        if (ti == 1) {
            int ai, xi;
            std::cin >> ai >> xi;
            for (int j = 0; j < ai; ++j) {
                sequence[j] += xi;
            }
            sum += static_cast<double>(xi) * ai;
        } else if (ti == 2) {
            int ki;
            std::cin >> ki;
            sequence.push_back(ki);
            sum += static_cast<double>(ki);
        } else if (ti == 3) {
            sum -= sequence.back();
            sequence.pop_back();
        }

        std::cout << std::fixed << std::setprecision(6) << sum / sequence.size() << '\n';
    }

    return 0;
}

