#include <iostream>
#include <vector>
using namespace std;

int power(int x, int y, int p) {
    int res = 1;
    x = x % p;
    while (y > 0) {
        if (y & 1)
            res = (res * x) % p;
        y = y >> 1;
        x = (x * x) % p;
    }
    return res;
}

bool isPrimitive(int n, int r) {
    vector<bool> seen(n, false);
    for (int i = 1; i <= n - 1; i++) {
        int k = power(r, i, n);
        if (seen[k])
            return false;
        seen[k] = true;
    }
    return true;
}

int countPrimitiveRoots(int n) {
    int count = 0;
    for (int r = 2; r <= n - 1; r++)
        if (isPrimitive(n, r))
            count++;
    return count;
}

int main() {
    int p;
    cin >> p;
    cout << countPrimitiveRoots(p) << endl;
    return 0;
}

