#include <iostream>
#include <vector>

using namespace std;

int eulerPhi(int p) {
    int result = p;
    for (int i = 2; i * i <= p; ++i) {
        if (p % i == 0) {
            while (p % i == 0) {
                p /= i;
            }
            result -= result / i;
        }
    }
    if (p > 1) {
        result -= result / p;
    }
    return result;
}

bool isPrimitiveRoot(int x, int p, const vector<int>& divisors) {
    for (int d : divisors) {
        if (d == p - 1) continue;
        long long power = 1;
        for (int j = 0; j < d; ++j) {
            power = (power * x) % p;
        }
        if (power == 1) return false;
    }
    return true;
}

int main() {
    int p;
    cin >> p;

    int phiP = eulerPhi(p);

    vector<int> divisors;
    for (int i = 1; i * i <= phiP; ++i) {
        if (phiP % i == 0) {
            divisors.push_back(i);
            if (i != phiP / i) {
                divisors.push_back(phiP / i);
            }
        }
    }

    int count = 0;
    for (int x = 2; x < p; ++x) {
        if (isPrimitiveRoot(x, p, divisors)) {
            ++count;
        }
    }

    cout << count;
}

