#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <utility>
#include <map>

using namespace std;

map<pair<int, int>, pair<int, int>> prevMove;
map<pair<int, int>, string> moveName;

string getMoveName(pair<int, int> move) {
    if (move == make_pair(-1, 0)) return "L";
    if (move == make_pair(1, 0)) return "R";
    if (move == make_pair(0, -1)) return "U";
    if (move == make_pair(0, 1)) return "D";
    if (move == make_pair(-1, -1)) return "LU";
    if (move == make_pair(-1, 1)) return "LD";
    if (move == make_pair(1, -1)) return "RU";
    if (move == make_pair(1, 1)) return "RD";
    return "";
}

int main() {
    string start, end;
    cin >> start >> end;

    pair<int, int> s = make_pair(start[0] - 'a', start[1] - '1');
    pair<int, int> t = make_pair(end[0] - 'a', end[1] - '1');

    queue<pair<int, int>> q;
    q.push(s);
    prevMove[s] = s;

    int dx[] = {-1, -1, -1, 0, 0, 1, 1, 1};
    int dy[] = {-1, 0, 1, -1, 1, -1, 0, 1};

    while (!q.empty()) {
        pair<int, int> u = q.front();
        q.pop();

        if (u == t) break;

        for (int i = 0; i < 8; i++) {
            pair<int, int> v = make_pair(u.first + dx[i], u.second + dy[i]);
            if (v.first >= 0 && v.first < 8 && v.second >= 0 && v.second < 8 && prevMove.find(v) == prevMove.end()) {
                q.push(v);
                prevMove[v] = u;
                moveName[v] = getMoveName(make_pair(dx[i], dy[i]));
            }
        }
    }

    vector<string> moves;
    pair<int, int> u = t;
    while (u != s) {
        moves.push_back(moveName[u]);
        u = prevMove[u];
    }

    cout << moves.size() << endl;
    for (auto it = moves.rbegin(); it != moves.rend(); it++) {
        cout << *it << endl;
    }

    return 0;
}

