bool is_goal(const State& state) {
    for (int num : state.nums) {
        if (num != 1) return false;
    }
    return true;
}

State add(const State& state, int i) {
    State next = state;
    next.nums[i] += 1;
    next.nums[(i + 1) % 4] += 1;
    next.ops.push_back("+" + to_string(i + 1));
    return next;
}

State divide(const State& state, int i) {
