#include <iostream>
#include <vector>
#include <queue>
#include <tuple>

using namespace std;

typedef tuple<vector<int>, vector<string>> State;

bool isSafeOpen(const vector<int>& numbers) {
    for (int num : numbers) {
        if (num != 1) return false;
    }
    return true;
}

vector<State> getNeighbors(const vector<int>& numbers) {
    vector<State> neighbors;
    int n = numbers.size();

    for (int i = 0; i < n; ++i) {
        int next = (i + 1) % n;
        vector<int> newNumbers = numbers;
        newNumbers[i]++;
        newNumbers[next]++;
        neighbors.emplace_back(newNumbers, vector<string>{ "+" + to_string(i + 1) });
    }

    for (int i = 0; i < n; ++i) {
        int next = (i + 1) % n;
        if (numbers[i] % 2 == 0 && numbers[next] % 2 == 0) {
            vector<int> newNumbers = numbers;
            newNumbers[i] /= 2;
            newNumbers[next] /= 2;
            neighbors.emplace_back(newNumbers, vector<string>{ "/" + to_string(i + 1) });
        }
    }

    return neighbors;
}

vector<string> bfs(const vector<int>& start) {
    queue<State> q;
    q.emplace(start, vector<string>{});

    while (!q.empty()) {
        auto [numbers, path] = q.front();
        q.pop();

        if (isSafeOpen(numbers)) {
            return path;
        }

        for (auto [newNumbers, newOps] : getNeighbors(numbers)) {
            q.emplace(newNumbers, vector<string>(path.begin(), path.end()));
            q.back().second.insert(q.back().second.end(), newOps.begin(), newOps.end());
        }
    }

    return {};
}

int main() {
    vector<int> numbers(4);
    cin >> numbers[0] >> numbers[1] >> numbers[2] >> numbers[3];

    vector<string> result = bfs(numbers);

    if (result.empty()) {
        cout << -1;
    } else {
        for (const string& op : result) {
            cout << op << "\n";
        }
    }

    return 0;
}

