        for (int i = n - 1; i > 0; --i) {
            for (int j = m - 1; j > 0; --j) {
                path.push_back({i + 1, j + 1});
            }
        }
        path.push_back({1, 1});
    } else {
        // Odd case, need one teleporter
        teleports.push_back({n, m, 1, 1});
        int teleported = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (teleported == 0 && i == n - 1 && j == m - 1) {
                    path.push_back({n, m});
                    path.push_back({1, 1});
                    teleported = 1;
                } else {
                    path.push_back({i + 1, j + 1});
                }
            }
        }
        for (int i = n - 1; i > 0; --i) {
            for (int j = m - 1; j > 0; --j) {
                path.push_back({i + 1, j + 1});
            }
        }
        path.push_back({1, 1});
