    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (res[i][j] != '.') continue;
            int x, y;
            bool horiz = (j == 0 || res[i][j-1] == '.');
            if (horiz) {
                x = i, y = j;
                while (y < n && res[x][y] == '.') ++y;
            } else {
                x = i, y = j;
                while (x < m && res[x][y] == '.') ++x;
            }
            int len = (horiz ? y : x) - (horiz ? j : i);
            for (const string& word : words) {
                if (word.size() == len) {
                    bool fits = true;
                    for (int k = 0; k < len; ++k) {
                        if (horiz && res[i][j+k] != '.' && res[i][j+k] != word[k]) {
                            fits = false;
                            break;
                        }
                        if (!horiz && res[i+k][j] != '.' && res[i+k][j] != word[k]) {
                            fits = false;
                            break;
                        }
                    }
                    if (fits) {
                        for (int k = 0; k < len; ++k) {
                            if (horiz) res[i][j+k] = word[k];
                            else res[i+k][j] = word[k];
                        }
                        if (check(res, words)) return true;
                        for (int k = 0; k < len; ++k) {
                            if (horiz) res[i][j+k] = '.';
                            else res[i+k][j] = '.';
                        }
                    }
                }
            }
            return false;
        }
    }
    return true;
}

void gen(int idx, int m, int n, vector<string>& cur, const vector<string>& words) {
