        if (i + n > 6) return false;
        for (int k = 0; k < n; ++k) {
            if (board[i + k][j] != '.' && board[i + k][j] != word[k]) return false;
        }
        return true;
    } else {
        if (j + n > 6) return false;
        for (int k = 0; k < n; ++k) {
            if (board[i][j + k] != '.' && board[i][j + k] != word[k]) return false;
        }
        return true;
    }
}

void placeWord(vector<string>& board, int i, int j, const string& word, bool vertical) {
    int n = word.size();
    if (vertical) {
        for (int k = 0; k < n; ++k) {
            board[i + k][j] = word[k];
        }
    } else {
        for (int k = 0; k < n; ++k) {
            board[i][j + k] = word[k];
        }
    }
}

void removeWord(vector<string>& board, int i, int j, const string& word, bool vertical) {
    int n = word.size();
    if (vertical) {
        for (int k = 0; k < n; ++k) {
            board[i + k][j] = '.';
        }
    } else {
        for (int k = 0; k < n; ++k) {
            board[i][j + k] = '.';
        }
    }
}

