        if (find(uniq.begin(), uniq.end(), min_s) == uniq.end()) {
            uniq.push_back(min_s);
        }
    }
    sort(uniq.begin(), uniq.end());
    if (k > uniq.size()) return "-1";
    return uniq[k-1];
}

