void genperm(int n, string colors) {
    if (n == 6) {
        int p = 0;
        for (int i = 0; i < 6; ++i) {
            p *= 6;
            p += colors[i] - 'A';
        }
        perm.push_back(p);
    } else {
        for (int i = n; i < 6; ++i) {
            swap(colors[n], colors[i]);
            genperm(n + 1, colors);
            swap(colors[n], colors[i]);
