    for (int i = len - 1; i >= 0; --i) {
        if (n[i] != '0') {
            last_zero_pos = i;
            break;
        }
    }

    if (last_zero_pos == len) {
        cout << "0";
        return 0;
    }

    string suffix = n.substr(last_zero_pos + 1);
    reverse(suffix.begin(), suffix.end());
    int min_non_zero_digit = 10;
    for (char c : suffix) {
        if (c - '0' < min_non_zero_digit) {
            min_non_zero_digit = c - '0';
        }
    }

    int min_deletions = len;
    for (int i = last_zero_pos; i >= 0; --i) {
        if ((n[i] - '0') % min_non_zero_digit == 0) {
