bool isPoisson(const std::vector<int>& answers, double lambda) {
    double expected[251] = {0};
    for (int i = 0; i <= 250; ++i) {
        expected[i] = 250 * std::pow(lambda, i) * std::exp(-lambda) / std::tgamma(i + 1);
    }

    double chi2 = 0;
    for (int k = 0; k < 251; ++k) {
        int count = 0;
        for (int answer : answers) {
            if (answer == k) {
                count++;
            }
        }
        if (expected[k] > 5) {
            chi2 += (count - expected[k]) * (count - expected[k]) / expected[k];
        }
    }

    return chi2 < 111.5; // 95% confidence level for 250 degrees of freedom
}

bool isUniform(const std::vector<int>& answers, int P) {
    double expected = 250.0 / (2 * P + 1);
    double chi2 = 0;

    std::vector<int> counts(2 * P + 1, 0);
    for (int answer : answers) {
        if (answer >= 0 && answer <= 2 * P) {
            counts[answer]++;
        }
    }

    for (int k = 0; k <= 2 * P; ++k) {
        if (expected > 5) {
            chi2 += (counts[k] - expected) * (counts[k] - expected) / expected;
        }
    }

    return chi2 < 111.5; // 95% confidence level for 2P degrees of freedom
}

