#include <cmath>
#include <algorithm>

using namespace std;

double poisson_pdf(int k, double lambda) {
    return exp(-lambda) * pow(lambda, k) / tgamma(k + 1);
}

double uniform_pdf(int k, double p) {
    if (k >= 0 && k <= 2 * p) return 1.0 / (2 * p + 1);
    return 0.0;
}

string classify_village(const vector<int>& answers) {
    int max_answer = *max_element(answers.begin(), answers.end());
    if (max_answer > 2000) return "uniform";

    double mean = 0;
    for (int answer : answers) mean += answer;
    mean /= answers.size();

    double variance = 0;
    for (int answer : answers) variance += (answer - mean) * (answer - mean);
    variance /= answers.size();

    double lambda = mean;
    double p = variance > lambda ? mean / 2 : 1000; // Heuristic to choose between distributions

    double poisson_likelihood = 1;
    double uniform_likelihood = 1;

    for (int answer : answers) {
        poisson_likelihood *= poisson_pdf(answer, lambda);
        uniform_likelihood *= uniform_pdf(answer, p);
    }

    // Compare likelihoods (or log-likelihoods for numerical stability)
    double log_poisson_likelihood = log(poisson_likelihood);
    double log_uniform_likelihood = log(uniform_likelihood);

    if (log_poisson_likelihood > log_uniform_likelihood) return "poisson";
    return "uniform";
}

