    int v;
    cin >> v;

    for (int i = 0; i < v; ++i) {
        vector<int> answers(250);
        for (int& answer : answers) cin >> answer;

        cout << classify_village(answers) << (i < v - 1 ? ' ' : '\n');
    }

    return 0;
}

