            // Uniform distribution
            int min_val = *std::min_element(village.begin(), village.end());
            int max_val = *std::max_element(village.begin(), village.end());
            std::cout << std::round((max_val + min_val) / 2.0) << "\n";
        }
    }
    return 0;
