#include <map>
#include <cmath>

using namespace std;

int estimate_population(const vector<int>& answers) {
    map<int, int> frequency;
    for (int answer : answers) {
        frequency[answer]++;
    }

    int n = answers.size();
    double expected_variance;
    int mode = -1;
    int max_count = 0;

    for (const auto& pair : frequency) {
        if (pair.second > max_count) {
            max_count = pair.second;
            mode = pair.first;
        }
    }

    double mean = 0.0;
    for (const auto& pair : frequency) {
        mean += pair.first * pair.second;
    }
    mean /= n;

    double variance = 0.0;
    for (const auto& pair : frequency) {
        variance += (pair.first - mean) * (pair.first - mean) * pair.second;
    }
    variance /= n;

    if (mean == variance) {
        return round(mean);
    } else {
        return mode;
    }
}

