    for (auto& [key, value] : freq) {
        minVal = min(minVal, key);
        maxVal = max(maxVal, key);
    }
    if (minVal == maxVal) return false;
    double lambda = 0;
    for (auto& [key, value] : freq) {
        if (key < minVal || key > maxVal) return false;
