    }
    lambda /= answers.size();
    double probSum = 0;
    for (auto& [key, value] : freq) {
        double prob = pow(lambda, key - minVal) * exp(-lambda) / tgamma(key - minVal + 1);
        probSum += prob * value;
    }
    return abs(probSum - answers.size()) < 1e-6;
