using namespace std;

bool isPoisson(const vector<int>& answers, int mean, int P) {
    map<int, int> freq;
    for (int ans : answers) {
        int original = ans + P;
        if (original < 0) return false;
        freq[original]++;
    }
    if (freq.size() != answers.size()) return false;
    double threshold = 1e-9;
    for (const auto& [val, count] : freq) {
        double expected = (exp(-mean) * pow(mean, val)) / factorial(val);
        if (abs(count - expected * answers.size()) > threshold) return false;
    }
    return true;
}

bool isUniform(const vector<int>& answers, int P) {
    set<int> uniqueValues;
    for (int ans : answers) {
        uniqueValues.insert(ans + P);
    }
    if (uniqueValues.size() != answers.size()) return false;
    return true;
}

long long factorial(int n) {
    long long result = 1;
    for (int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

