bool canRecover(const std::vector<int>& a, const std::vector<int>& b) {
    int n = a.size();
    int k = b.size();
    std::vector<int> nonZeros;

    for (int i = 0; i < n; ++i) {
        if (a[i] != 0) {
            nonZeros.push_back(a[i]);
        }
    }

    std::sort(nonZeros.begin(), nonZeros.end());

    std::vector<int> bCopy = b;
    std::sort(bCopy.begin(), bCopy.end());

    int i = 0, j = 0;
    while (i < n && j < k) {
        if (a[i] == 0) {
            if (nonZeros.empty() || bCopy[j] <= nonZeros.back()) {
                return true;
            }
            while (i < n && a[i] == 0) {
                ++i;
            }
            --j;
        } else {
            ++i;
        }
        ++j;
    }

    return false;
}

