#include <bits/stdc++.h>
using namespace std;

const double PI = 3.14159265358979323846;

struct Circle {
    double x, y, r;
};

vector<Circle> circles;

double area_of_intersection(const Circle &a, const Circle &b) {
    double d = hypot(a.x - b.x, a.y - b.y);
    if (d >= a.r + b.r) return 0.0;
    if (d <= abs(a.r - b.r)) return PI * min(a.r, b.r) * min(a.r, b.r);

    double x = (a.r * a.r - b.r * b.r + d * d) / (2 * d);
    double y = sqrt(a.r * a.r - x * x);
    double x2 = (b.r * b.r - a.r * a.r + d * d) / (2 * d);
    double y2 = sqrt(b.r * b.r - x2 * x2);

    return x * y + atan2(y, x) * a.r * a.r - x2 * y2 - atan2(y2, x2) * b.r * b.r;
}

double total_spaciousness(const vector<int> &group) {
    double total_area = 0.0;
    for (int i : group) {
        total_area += PI * circles[i].r * circles[i].r;
        for (int j : group) {
            if (i < j) {
                total_area -= area_of_intersection(circles[i], circles[j]);
            }
        }
    }
    return total_area;
}

int main() {
    int n;
    cin >> n;
    circles.resize(n);
    for (auto &c : circles) {
        cin >> c.x >> c.y >> c.r;
    }

    double max_spaciousness = 0.0;
    for (int mask = 0; mask < (1 << n); ++mask) {
