                group1.push_back(i);
            } else {
                group2.push_back(i);
            }
        }
        double spaciousness = total_spaciousness(group1) + total_spaciousness(group2);
        max_spaciousness = max(max_spaciousness, spaciousness);
    }

    cout << fixed << setprecision(10) << max_spaciousness << endl;
}

