struct Circle {
    double x, y, r;
    Circle(double x, double y, double r) : x(x), y(y), r(r) {}
};

bool intersect(Circle a, Circle b) {
    double dist = sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
    return dist < a.r + b.r;
}

double area_of_intersection(Circle a, Circle b) {
    double d = sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
    if (d >= a.r + b.r) return 0.0;
    if (d + a.r <= b.r) return PI * a.r * a.r;
    if (d + b.r <= a.r) return PI * b.r * b.r;
    double x = (a.r * a.r - b.r * b.r + d * d) / (2 * d);
    double y = sqrt(a.r * a.r - x * x);
    double sector_a = (acos(x / a.r) * a.r * a.r);
    double sector_b = (acos((d - x) / b.r) * b.r * b.r);
    double triangle_a = (0.5 * x * y);
    double triangle_b = (0.5 * (d - x) * y);
    return sector_a + sector_b - triangle_a - triangle_b;
}

